mapper.select:
SELECT id, prescription_name AS prescriptionName, patient_name AS patientName, gender, age, medical_record_number AS medicalRecordNumber, disease_type AS diseaseType, enrollment_institution AS enrollmentInstitution, execution_institution AS executionInstitution, prescription_status AS prescriptionStatus, prescribing_doctor AS prescribingDoctor, created_time AS createdTime FROM patient_prescribed_exercise
AND disease_type = #{query.diseaseType}
AND prescription_status = #{query.prescriptionStatus}
AND enrollment_institution = #{query.enrollmentInstitution}
AND execution_institution = #{query.executionInstitution}
AND ( patient_name LIKE CONCAT('%', #{query.searchKeyword}, '%') OR medical_record_number LIKE CONCAT('%', #{query.searchKeyword}, '%') )
ORDER BY created_time DESC
